    const values={square_feet:section.totals?.square_feet,perimeter_lf:section.totals?.perimeter_lf,caulking_lf:section.totals?.caulking_lf,head_sill_qty:section.totals?.head_sill_qty,pre_tax_material_cost:section.pre_tax_material_cost,pre_tax_material_cost_per_sf:section.pre_tax_material_cost_per_sf};
