function historicalKey(code){return String(code||"").toUpperCase().replace(/[^A-Z0-9]/g,"")}
function storeHistoricalComparisons(payload){state.historyComparisons=Object.fromEntries((payload?.comparisons||[]).map(item=>[historicalKey(item.code),item]));reconcileHistoryIndicators()}
function historyTooltip(item){if(!item)return"Historical comparison is loading.";if(item.status==="unavailable")return item.message||"Current sell-value Dollars per Square Foot is unavailable.";const range=item.date_range||{},definition=item.category_definition||"Aggressive is at or below the historical 25th percentile; Conservative is at or above the 75th percentile.";return [item.current_value===null||item.current_value===undefined?null:`Current ${money(item.current_value,"currency_per_unit")}/SF`,item.median===null||item.median===undefined?null:`Historical median ${money(item.median,"currency_per_unit")}/SF`,item.percentile===null||item.percentile===undefined?null:`${number(item.percentile)}th percentile`,`${item.sample_size||0} comparable project${item.sample_size===1?"":"s"}`,range.start||range.end?`${range.start||"—"} to ${range.end||"—"}`:null,definition].filter(Boolean).join(" · ")}
function historyIndicator(code){
  const item=state.historyComparisons[historicalKey(code)];
  if(!item)return `<div class="history-indicator loading no-history" aria-label="Loading historical comparison"><span class="history-readout"><strong>History loading</strong></span><span class="history-track" aria-hidden="true"></span></div>`;
  const status=String(item.status||"").toLowerCase().replace(/[_\s]+/g,"-"),category=item.category||item.classification||(status==="insufficient-history"?"Insufficient history":status==="limited-history"?"Limited history":"Unavailable"),tone=String(category).toLowerCase().replace(/[_\s]+/g,"-"),sample=Number(item.sample_size||0),hasQuartiles=sample>0&&[item.q1,item.median,item.q3].every(value=>value!==null&&value!==undefined&&Number.isFinite(Number(value))),hasCurrent=hasQuartiles&&item.percentile!==null&&item.percentile!==undefined&&Number.isFinite(Number(item.percentile)),percentile=hasCurrent?Math.max(2,Math.min(98,Number(item.percentile))):null,readout=item.readout||(status==="insufficient-history"?`Insufficient history · ${sample} comparable bid${sample===1?"":"s"}`:status==="limited-history"?`Limited history · ${sample} comparable bid${sample===1?"":"s"}`:status==="unavailable"?"Unavailable":`${category} · ${number(item.percentile)}th percentile · ${sample} comparable bid${sample===1?"":"s"}`),chart=hasQuartiles?`<i class="anchor q1"></i><i class="anchor median"></i><i class="anchor q3"></i>${hasCurrent?'<i class="current"></i>':""}`:"";
  return `<button type="button" class="history-indicator ${esc(tone)} ${hasQuartiles?"":"no-history"}" ${hasCurrent?`style="--history-position:${percentile}%"`:""} data-history-code="${esc(code)}" data-tooltip="${esc(historyTooltip(item))}" aria-label="Historical position for ${esc(code)}: ${esc(readout)}"><span class="history-readout"><strong>${esc(readout)}</strong></span><span class="history-track" aria-hidden="true">${chart}</span></button>`;
}
const HISTORY_VISUAL_BANDS=[{key:"very-aggressive",label:"Very Aggressive"},{key:"aggressive",label:"Aggressive"},{key:"normal",label:"Normal"},{key:"conservative",label:"Conservative"},{key:"very-conservative",label:"Very Conservative"}];
function compactHistoryDate(value){if(!value)return null;const date=new Date(value);return Number.isNaN(date.getTime())?null:new Intl.DateTimeFormat("en-US",{month:"short",year:"numeric",timeZone:"UTC"}).format(date)}
