  const projectId=state.doc?.project?.id,section=opener?.closest?.("[data-frame-section-id]"),context={projectId,bidVersion:state.doc?.project?.bid_version?.display||null,page:state.page,costCode:code,frameSectionId:section?.dataset.frameSectionId||null},sequence=++state.historyDetailRequest;if(!projectId)return;
