    const [r,c]=await Promise.all([api("/api/projects",{method:"POST",body:JSON.stringify({name})}),api("/api/configurations")]);if(request!==state.openProjectRequest)return;
    const referenceConfig=c.configurations.reduce((a,b)=>Number(a.version||0)>Number(b.version||0)?a:b),config=c.configurations.find(x=>x.id===r.project.project.configuration_id)||referenceConfig;
    transitionWorkspaceIdentity(r.project.project.id);state.doc=r.project;state.page="project";state.referenceConfig=referenceConfig;state.config=config;saveState("saved","Saved");
    $("#welcome").hidden=true;$("#workspace").hidden=false;updateRoute(state.doc.project.id,state.page);updateHeader();buildNav();render();loadHistoricalComparisons();loadProjects();
