window.addEventListener("beforeunload",e=>{if(state.dirty){e.preventDefault();e.returnValue="Unsaved project changes remain."}});
window.addEventListener("popstate",async()=>{const route=currentRoute();if(state.dirty&&!confirm("Unsaved changes remain. Continue navigating and discard them?")){updateRoute(state.doc?.project.id,state.page);return}closeHistoricalDetail();setMobileNavigation(false);if(!route.projectId){showProjectList({push:false});return}if(state.doc?.project.id===route.projectId){state.page=route.page;render();buildNav();return}await openProject(route.projectId,false,route.page,"none")});

async function init(){setMobileNavigation(false);const [r,health]=await Promise.all([api("/api/roles"),api("/api/health")]);$("#roleSelect").innerHTML=r.roles.map(x=>`<option ${x===(localStorage.getItem("mw-role")||"Estimator")?"selected":""}>${x}</option>`).join("");$("#actorInput").value=localStorage.getItem("mw-actor")||"Local User";$("#softwareVersion").textContent=health.software_version?`v${health.software_version}`:"version unavailable";const route=currentRoute();await loadProjects();if(route.projectId)await openProject(route.projectId,false,route.page,"replace");else{updateRoute(null,null,{replace:true});buildNav()}}
init().catch(e=>toast(e.message,true));
